 async void SaveLast30(string preset){cfg.CapturePreset=preset;SaveConfig();if(captureWindow!=null)captureWindow.Hide();string output=Path.Combine(Path.GetTempPath(),"Awl-last-30s-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".mp4");var progressWindow=new Window{Title="Saving last 30 seconds",Width=330,Height=92,WindowStyle=WindowStyle.None,ResizeMode=ResizeMode.NoResize,AllowsTransparency=true,Background=Brushes.Transparent,Topmost=true,ShowInTaskbar=false,WindowStartupLocation=WindowStartupLocation.CenterScreen};ExcludeCaptureWindow(progressWindow);var row=new StackPanel{Orientation=Orientation.Horizontal};row.Children.Add(BuilderSvgIcon("history",24,accentBrush));var label=Text("Encoding the last 30 seconds…",13);label.Margin=new Thickness(12,0,0,0);row.Children.Add(label);SetCaptureContent(progressWindow,PopupSurface(row,18),"Recording controls",330,92);progressWindow.Show();bool saved=false;try{if(rollingRecorder==null)StartRollingCapture();var recorder=rollingRecorder;rollingRecorder=null;if(recorder!=null)await Task.Run(()=>recorder.Stop());saved=await Task.Run(()=>EncodeRollingCapture(recorder,preset,output));StartRollingCapture();}catch(Exception error){Log("Last 30 seconds: "+error.Message);}progressWindow.Close();if(saved)ShowCaptureReview(output,true,TimeSpan.FromSeconds(30));else{MessageBox.Show("The rolling buffer does not contain a complete frame yet. Leave Awl running for a few seconds, then try again.","Last 30 seconds");if(captureWindow!=null)captureWindow.Show();}}
 void StartRollingCapture(){if(rollingRecorder!=null)return;try{string runtime=CaptureRuntime();if(String.IsNullOrEmpty(runtime))return;string directory=Path.Combine(Root,"CaptureBuffer");Directory.CreateDirectory(directory);foreach(string file in Directory.GetFiles(directory,"segment-*.mp4"))try{File.Delete(file);}catch{}var rect=TargetScreen().Bounds;rollingRecorder=new RollingRecorder(this,runtime,rect,directory);rollingRecorder.Start();}catch(Exception error){Log("Rolling capture: "+error.Message);}}
 bool EncodeRollingCapture(RollingRecorder recorder,string preset,string output){if(recorder==null)return false;var ordered=recorder.Files().OrderBy(x=>File.GetLastWriteTimeUtc(x)).ToList();var files=ordered.Skip(Math.Max(0,ordered.Count-6)).ToList();if(files.Count==0)return false;string list=Path.Combine(Path.GetDirectoryName(files[0]),"concat-"+Guid.NewGuid().ToString("N")+".txt");File.WriteAllLines(list,files.Select(x=>"file '"+x.Replace("'","'\\''")+"'"));var settings=PresetValues(preset,TargetScreen().Bounds);string args="-y -f concat -safe 0 -i \""+list+"\" -vf scale="+settings.Item1+":"+settings.Item2+":flags=lanczos -r 15 -c:v libopenh264 -b:v "+settings.Item3+" -maxrate "+settings.Item3+" -bufsize "+(settings.Item3*2)+" -pix_fmt yuv420p -movflags +faststart \""+output+"\"";var process=Process.Start(new ProcessStartInfo(CaptureRuntime(),args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true});process.StandardError.ReadToEnd();process.WaitForExit();try{File.Delete(list);}catch{}return process.ExitCode==0&&File.Exists(output)&&new FileInfo(output).Length>1000;} Forms.Screen TargetScreen(){return Forms.Screen.PrimaryScreen;}
