 void ShowRegionSelector(Action<System.Drawing.Rectangle> selected){if(captureWindow!=null)captureWindow.Hide();var bounds=Forms.SystemInformation.VirtualScreen;captureOverlay=new Window{Title="Select capture region",Left=bounds.Left,Top=bounds.Top,Width=bounds.Width,Height=bounds.Height,WindowStyle=WindowStyle.None,ResizeMode=ResizeMode.NoResize,AllowsTransparency=true,Background=new SolidColorBrush(Color.FromArgb(86,0,0,0)),Topmost=true,ShowInTaskbar=false,Cursor=Cursors.Cross};ExcludeCaptureWindow(captureOverlay);var canvas=new Canvas();var outline=new Rectangle{Stroke=accentBrush,StrokeThickness=2,Fill=new SolidColorBrush(Color.FromArgb(24,90,230,180)),Visibility=Visibility.Collapsed};canvas.Children.Add(outline);captureOverlay.Content=canvas;Point start=new Point();captureOverlay.MouseLeftButtonDown+=delegate(object sender,MouseButtonEventArgs e){start=e.GetPosition(canvas);outline.Visibility=Visibility.Visible;Canvas.SetLeft(outline,start.X);Canvas.SetTop(outline,start.Y);captureOverlay.CaptureMouse();};captureOverlay.MouseMove+=delegate(object sender,MouseEventArgs e){if(e.LeftButton!=MouseButtonState.Pressed)return;var now=e.GetPosition(canvas);Canvas.SetLeft(outline,Math.Min(start.X,now.X));Canvas.SetTop(outline,Math.Min(start.Y,now.Y));outline.Width=Math.Abs(now.X-start.X);outline.Height=Math.Abs(now.Y-start.Y);};captureOverlay.MouseLeftButtonUp+=delegate(object sender,MouseButtonEventArgs e){var now=e.GetPosition(canvas);var a=captureOverlay.PointToScreen(start);var b=captureOverlay.PointToScreen(now);var rect=System.Drawing.Rectangle.FromLTRB((int)Math.Min(a.X,b.X),(int)Math.Min(a.Y,b.Y),(int)Math.Max(a.X,b.X),(int)Math.Max(a.Y,b.Y));captureOverlay.ReleaseMouseCapture();captureOverlay.Close();captureOverlay=null;selected(rect);};captureOverlay.KeyDown+=delegate(object sender,KeyEventArgs e){if(e.Key==Key.Escape){captureOverlay.Close();captureOverlay=null;if(captureWindow!=null)captureWindow.Show();}};captureOverlay.Show();captureOverlay.Activate();}
 System.Drawing.Bitmap CaptureBitmap(System.Drawing.Rectangle rect,bool resize=false,int width=0,int height=0){var source=new System.Drawing.Bitmap(rect.Width,rect.Height,System.Drawing.Imaging.PixelFormat.Format32bppArgb);using(var graphics=System.Drawing.Graphics.FromImage(source)){IntPtr desktop=GetDC(IntPtr.Zero),target=graphics.GetHdc();bool copied=false;try{if(desktop!=IntPtr.Zero)copied=BitBlt(target,0,0,rect.Width,rect.Height,desktop,rect.Left,rect.Top,0x40CC0020);}finally{graphics.ReleaseHdc(target);if(desktop!=IntPtr.Zero)ReleaseDC(IntPtr.Zero,desktop);}if(!copied)try{graphics.CopyFromScreen(rect.Left,rect.Top,0,0,rect.Size,System.Drawing.CopyPixelOperation.SourceCopy);}catch{}if(!cfg.CaptureHideCursor)DrawMouse(graphics,rect);}if(!resize||width==rect.Width&&height==rect.Height)return source;var result=new System.Drawing.Bitmap(width,height,System.Drawing.Imaging.PixelFormat.Format32bppArgb);using(var graphics=System.Drawing.Graphics.FromImage(result)){graphics.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;graphics.DrawImage(source,0,0,width,height);}source.Dispose();return result;}
