 void HideCapturedSurfaces(){captureHiddenWindows.Clear();if(cfg.CaptureHideShell)foreach(Window window in Current.Windows.Cast<Window>().ToArray()){if(window==captureRecordWindow||window==captureOverlay||window==captureReviewWindow||window==captureWindow||!window.IsVisible)continue;captureHiddenWindows.Add(window);window.Hide();}if(captureWindow!=null)captureWindow.Hide();if(cfg.CaptureHideDesktopIcons){desktopIcons=FindWindowEx(Native.FindWindow("Progman",null),IntPtr.Zero,"SHELLDLL_DefView",null);if(desktopIcons!=IntPtr.Zero)Native.ShowWindow(desktopIcons,0);}}
