 string[] CapturePresets(System.Drawing.Rectangle rect){var values=new List<string>{"Discord Free","Discord Basic","Discord Nitro"};if(rect.Height>=480)values.Add("480p");if(rect.Height>=720)values.Add("720p");if(rect.Height>=1080)values.Add("1080p");if(rect.Height>=1440)values.Add("1440p");if(rect.Height>=2160)values.Add("4K");values.Add("Native · "+rect.Width+"×"+rect.Height);return values.Distinct().ToArray();}
 Tuple<int,int,int,long> PresetValues(string preset,System.Drawing.Rectangle source){int height=source.Height,bitrate=6000000;long limit=0;if(preset=="Discord Free"){height=Math.Min(720,height);bitrate=900000;limit=10L*1000*1000;}else if(preset=="Discord Basic"){height=Math.Min(1080,height);bitrate=3500000;limit=50L*1000*1000;}else if(preset=="Discord Nitro"){bitrate=10000000;limit=500L*1000*1000;}else if(preset=="480p"){height=Math.Min(480,height);bitrate=1200000;}else if(preset=="720p"){height=Math.Min(720,height);bitrate=2800000;}else if(preset=="1080p"){height=Math.Min(1080,height);bitrate=6000000;}else if(preset=="1440p"){height=Math.Min(1440,height);bitrate=11000000;}else if(preset=="4K"){height=Math.Min(2160,height);bitrate=22000000;}int width=(int)Math.Round(source.Width*(height/(double)source.Height));width=Math.Max(2,width/2*2);height=Math.Max(2,height/2*2);return Tuple.Create(width,height,bitrate,limit);}
