 public string CaptureSelfTest(){try{string runtime=CaptureRuntime();if(String.IsNullOrEmpty(runtime))return "FAILED: capture runtime missing";string output=Path.Combine(Path.GetTempPath(),"Awl-capture-test.mp4");var process=Process.Start(new ProcessStartInfo(runtime,"-y -f rawvideo -pixel_format bgra -video_size 64x64 -framerate 10 -i pipe:0 -an -c:v libopenh264 -b:v 180000 -pix_fmt yuv420p \""+output+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardError=true});process.ErrorDataReceived+=delegate{};process.BeginErrorReadLine();var frame=new byte[64*64*4];for(int i=0;i<20;i++){for(int p=0;p<frame.Length;p+=4){frame[p]=(byte)(i*9);frame[p+1]=(byte)(80+i*4);frame[p+2]=120;frame[p+3]=255;}process.StandardInput.BaseStream.Write(frame,0,frame.Length);}process.StandardInput.Close();process.WaitForExit();bool valid=process.ExitCode==0&&File.Exists(output)&&new FileInfo(output).Length>1000;try{File.Delete(output);}catch{}return valid?"Capture runtime encodes standalone MP4":"FAILED: capture runtime encoding";}catch(Exception error){return "FAILED: "+error.Message;}}
