 sealed class RollingRecorder{
  readonly Shell owner;readonly string ffmpeg,directory;readonly System.Drawing.Rectangle area;readonly int width,height;readonly Thread thread;readonly bool testPattern;volatile bool running;Process process;
  public RollingRecorder(Shell owner,string ffmpeg,System.Drawing.Rectangle area,string directory,bool testPattern=false){this.owner=owner;this.ffmpeg=ffmpeg;this.area=area;this.directory=directory;this.testPattern=testPattern;double scale=Math.Min(1,720.0/Math.Max(1,area.Height));width=Math.Max(2,((int)Math.Round(area.Width*scale))/2*2);height=Math.Max(2,((int)Math.Round(area.Height*scale))/2*2);thread=new Thread(Run){IsBackground=true,Name="Awl rolling capture"};}
  public void Start(){running=true;thread.Start();}
  public string[] Files(){try{return Directory.GetFiles(directory,"segment-*.mp4").Where(x=>new FileInfo(x).Length>1000).ToArray();}catch{return new string[0];}}
  void Run(){try{string pattern=Path.Combine(directory,"segment-%02d.mp4");string args="-y -f rawvideo -pixel_format bgra -video_size "+width+"x"+height+" -framerate 10 -i pipe:0 -an -c:v libopenh264 -b:v 2500000 -maxrate 2500000 -bufsize 5000000 -g 10 -pix_fmt yuv420p -f segment -segment_time 5 -segment_wrap 7 -reset_timestamps 1 \""+pattern+"\"";var errors=new System.Text.StringBuilder();process=Process.Start(new ProcessStartInfo(ffmpeg,args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardError=true});process.ErrorDataReceived+=delegate(object sender,DataReceivedEventArgs e){if(e.Data!=null)errors.AppendLine(e.Data);};process.BeginErrorReadLine();var frame=TimeSpan.FromMilliseconds(100);while(running){var began=DateTime.UtcNow;using(var bitmap=testPattern?new System.Drawing.Bitmap(width,height,System.Drawing.Imaging.PixelFormat.Format32bppArgb):owner.CaptureBitmap(area,true,width,height)){var data=bitmap.LockBits(new System.Drawing.Rectangle(0,0,width,height),System.Drawing.Imaging.ImageLockMode.ReadOnly,System.Drawing.Imaging.PixelFormat.Format32bppArgb);try{int bytes=Math.Abs(data.Stride)*height;var buffer=new byte[bytes];Marshal.Copy(data.Scan0,buffer,0,bytes);process.StandardInput.BaseStream.Write(buffer,0,buffer.Length);}finally{bitmap.UnlockBits(data);}}var left=frame-(DateTime.UtcNow-began);if(left.TotalMilliseconds>1)Thread.Sleep(left);}try{process.StandardInput.Close();}catch{}if(!process.WaitForExit(8000))process.Kill();if(process.ExitCode!=0)Log("Rolling ffmpeg: "+errors.ToString());}catch(Exception error){Log("Rolling recorder: "+error.Message+(process!=null?" · ffmpeg exited="+process.HasExited:""));try{if(process!=null&&!process.HasExited)process.Kill();}catch{}}}
  public void Stop(){running=false;if(thread.IsAlive)thread.Join(10000);}
 }

 sealed class ScreenRecorder{
  readonly Shell owner;readonly string ffmpeg;readonly System.Drawing.Rectangle area;readonly int width,height,bitrate;readonly Thread thread;volatile bool running;long framesWritten;public volatile bool Paused;Process process;public string Output{get;private set;}public long Size{get{long actual=0;try{actual=File.Exists(Output)?new FileInfo(Output).Length:0;}catch{}long estimated=(long)(Interlocked.Read(ref framesWritten)*(long)bitrate/8/20*.72);return actual>1024?actual:estimated;}}
  public ScreenRecorder(Shell owner,string ffmpeg,System.Drawing.Rectangle area,int width,int height,int bitrate,string output){this.owner=owner;this.ffmpeg=ffmpeg;this.area=area;this.width=width;this.height=height;this.bitrate=bitrate;Output=output;thread=new Thread(Run){IsBackground=true,Name="Awl screen recorder"};}
