  void Run(){try{string args="-y -f rawvideo -pixel_format bgra -video_size "+width+"x"+height+" -framerate 20 -i pipe:0 -an -c:v libopenh264 -b:v "+bitrate+" -maxrate "+bitrate+" -bufsize "+(bitrate*2)+" -pix_fmt yuv420p -g 20 -flush_packets 1 -movflags +frag_keyframe+empty_moov+default_base_moof \""+Output+"\"";process=Process.Start(new ProcessStartInfo(ffmpeg,args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardError=true});process.ErrorDataReceived+=delegate{};process.BeginErrorReadLine();var frame=TimeSpan.FromMilliseconds(50);while(running){var began=DateTime.UtcNow;if(!Paused)using(var bitmap=owner.CaptureBitmap(area,true,width,height)){var data=bitmap.LockBits(new System.Drawing.Rectangle(0,0,width,height),System.Drawing.Imaging.ImageLockMode.ReadOnly,System.Drawing.Imaging.PixelFormat.Format32bppArgb);try{int bytes=Math.Abs(data.Stride)*height;var buffer=new byte[bytes];Marshal.Copy(data.Scan0,buffer,0,bytes);process.StandardInput.BaseStream.Write(buffer,0,buffer.Length);Interlocked.Increment(ref framesWritten);}finally{bitmap.UnlockBits(data);}}var left=frame-(DateTime.UtcNow-began);if(left.TotalMilliseconds>1)Thread.Sleep(left);}try{process.StandardInput.Close();}catch{}if(!process.WaitForExit(8000))process.Kill();}catch(Exception error){Log("Recorder: "+error.Message);try{if(process!=null&&!process.HasExited)process.Kill();}catch{}}}
  public void Stop(){running=false;if(thread.IsAlive)thread.Join(10000);}
 }
